from pathlib import Path
P=Path(__file__).resolve().parents[1]/'dist'/'assets'
def svg(name,body,title):
 text=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 700 250" role="img" aria-labelledby="title"><title id="title">{title}</title><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#486744"/></marker></defs><style>text{{font-family:Arial,sans-serif;fill:#284d3c;font-size:16px}}.wire{{fill:none;stroke:#486744;stroke-width:2.5}}.accent{{fill:none;stroke:#9bb568;stroke-width:3}}.label{{font-size:13px;fill:#708165}}</style>{body}</svg>'''
 (P/(name+'.svg')).write_text(text)
svg('transformer','''<rect x="230" y="35" width="220" height="160" rx="12" fill="#e4ebd8" stroke="#a0b089" stroke-width="2"/><rect x="282" y="72" width="118" height="88" rx="5" fill="#f9fbf4" stroke="#a0b089"/><path class="wire" d="M110 60h112c32 0 32 25 0 25s-32 25 0 25 32 25 0 25-32 25 0 25H110"/><path class="wire" d="M575 60H458c-26 0-26 16 0 16s26 16 0 16-26 16 0 16 26 16 0 16-26 16 0 16 26 16 0 16H575"/><path class="accent" d="M310 52h88q32 0 32 32v49" marker-end="url(#arrow)"/><text x="100" y="115">V₁</text><text x="565" y="115">V₂</text><text x="177" y="214">N₁ turns</text><text x="445" y="214">N₂ turns</text><text x="322" y="125">Φ(t)</text><text class="label" x="227" y="243">Shared changing flux · frequency unchanged</text>''','Two windings linked by a magnetic core; common changing flux')
svg('induction','''<rect x="20" y="75" width="130" height="80" rx="8" fill="#e7eedb"/><rect x="215" y="75" width="130" height="80" rx="8" fill="#e7eedb"/><rect x="410" y="75" width="125" height="80" rx="8" fill="#e7eedb"/><rect x="585" y="75" width="100" height="80" rx="8" fill="#d7e5ba"/><g class="wire" marker-end="url(#arrow)"><path d="M150 115h65"/><path d="M345 115h65"/><path d="M535 115h50"/><path d="M180 115v80"/><path d="M374 115v80"/><path d="M559 115v80"/></g><text x="43" y="109">Electrical</text><text x="50" y="132">input</text><text x="231" y="109">Air-gap</text><text x="251" y="132">P₉</text><text x="432" y="109">Gross</text><text x="421" y="132">(1 − s)P₉</text><text x="610" y="109">Shaft</text><text x="605" y="132">output</text><text class="label" x="130" y="218">Stator losses</text><text class="label" x="321" y="218">Rotor loss: sP₉</text><text class="label" x="510" y="218">Mechanical loss</text>''','Power flow from input to air gap to gross mechanical to shaft output, with losses at each stage')
svg('rc','''<path class="wire" d="M70 80V45h65m30 0h30l10-9 13 18 13-18 13 18 13-18 10 9h43v53m0 16v64H70v-58"/><path class="wire" d="M135 45l28-18M290 98h40m-40 16h40"/><circle class="wire" cx="70" cy="101" r="21"/><text x="61" y="107">+</text><text x="217" y="28">R</text><text x="341" y="110">C</text><text class="label" x="90" y="213">Switch closes at t = 0</text><path class="wire" d="M422 180V35m0 145h235" marker-end="url(#arrow)"/><path class="accent" d="M422 180C458 97 488 60 535 50S610 44 649 44"/><path d="M422 44h230M493 180v-104" stroke="#b7c5a6" stroke-dasharray="4 5"/><text class="label" x="407" y="32">vC</text><text class="label" x="662" y="185">t</text><text class="label" x="480" y="205">τ = RC</text><text class="label" x="490" y="233">At τ: 63.2% charged</text>''','RC circuit and exponential capacitor charging curve, reaching 63.2 percent at one time constant')
svg('phasor','''<path class="wire" d="M155 192h290" marker-end="url(#arrow)"/><path class="wire" d="M445 192V55" marker-end="url(#arrow)"/><path class="accent" d="M155 192L445 55" marker-end="url(#arrow)"/><path d="M215 192A60 60 0 0 0 210 166" fill="none" stroke="#9bb568" stroke-width="2"/><text x="258" y="217">VR = IR (in phase with I)</text><text x="464" y="115">VL = IXL</text><text x="265" y="91">V = VR + jVL</text><text x="222" y="177">φ</text><text class="label" x="212" y="244">Use the vector triangle: |V|² = VR² + VL²</text>''','Series RL voltage phasor triangle: resistive voltage in phase with current; inductive voltage vertical')
svg('buck','''<path class="wire" d="M70 90V48h80m35 0h80c0-25 22-25 22 0s22 25 22 0 22-25 22 0 22 25 22 0h192v35m0 55v53H70v-60"/><circle class="wire" cx="70" cy="110" r="20"/><text x="61" y="116">+</text><path class="wire" d="M150 48l36-22M227 48v73m0 25v45M448 48v55m0 13v75M430 103h36m-36 13h36"/><path d="M217 123h20l-10 19z" fill="none" stroke="#486744" stroke-width="2"/><path class="wire" d="M215 145h24"/><rect class="wire" x="531" y="83" width="26" height="55"/><text x="143" y="17">Switch</text><text x="302" y="23">L</text><text x="472" y="116">C</text><text x="576" y="116">Load</text><text class="label" x="173" y="220">OFF: diode carries inductor current upward</text><text class="label" x="201" y="244">CCM, ideal components: Vout = D × Vin</text><text class="label" x="15" y="152">Vin</text>''','Ideal buck converter with switch, inductor, freewheeling diode, capacitor and load')
# Correct freewheel diode polarity: anode at ground, cathode at switching node.
p=P/'buck.svg';t=p.read_text();t=t.replace('M217 123h20l-10 19z','M217 142h20l-10-19z').replace('M215 145h24','M215 121h24');p.write_text(t)
print('5 teaching diagrams written')
